SPRITES = [SPRITE_1, SPRITE_2, SPRITE_3, SPRITE_4]

# Séquence : 80% walk (frames 3+4), 20% idle (frames 1+2)
# [idle1, idle2, walk3, walk4, walk3, walk4, walk3, walk4, walk3, walk4]
SEQUENCE = [0, 1, 2, 3, 2, 3, 2, 3, 2, 3]


def draw_sprite(pixels, sprite_data, offset_x, flipped=False):
    """Dessine un sprite sur le canvas, avec offset X et flip optionnel."""
    for (sx, sy), color in sprite_data.items():
        if flipped:
            px = offset_x + (W - 1 - sx)
        else:
            px = offset_x + sx - (W // 2 - 8)
        py = sy
        if 0 <= px < W and 0 <= py < H:
            pixels[py * W + px] = color


def render_frame(frame_idx, x, direction):
    pixels = [(0, 0, 0)] * (W * H)
    sprite = SPRITES[frame_idx]
    # Centre le sprite horizontalement à la position x
    ox = x - 16
    flipped = (direction < 0)
    for (sx, sy), color in sprite.items():
        if flipped:
            px = ox + (31 - sx)
        else:
            px = ox + sx
        py = sy
        if 0 <= px < W and 0 <= py < H:
            pixels[py * W + px] = color
    return pixels


def pixels_to_png(pixels):
    img = Image.new("RGB", (W, H))
    img.putdata(pixels)
    out = BytesIO()
    img.save(out, format="PNG", optimize=False)
    return out.getvalue()


async def sprite_animation(
    duration=60.0,
    fps=8.0,        # 8 FPS = animation fluide pour un sprite
    speed=1,        # pixels par frame
):
    x = 16
    direction = 1
    seq_idx = 0
    delay = 1.0 / fps

    async with BleDisplaySession(MAC_ADDRESS) as session:
        print(f"Stickman sprite pendant {duration}s... (Echap pour arreter)")
        t0 = asyncio.get_event_loop().time()
        while state["running"] and asyncio.get_event_loop().time() - t0 < duration:
            frame_idx = SEQUENCE[seq_idx % len(SEQUENCE)]
            pixels = render_frame(frame_idx, x, direction)
            png = pixels_to_png(pixels)
            await session.send_png(png, delay=0.0)

            x += direction * speed
            seq_idx += 1

            # Rebond sur les bords
            if x >= W - 6:
                x = W - 6
                direction = -1
            if x <= 6:
                x = 6
                direction = 1

            await asyncio.sleep(delay)
        print("Animation terminée.")


listener = keyboard.Listener(on_press=on_press)
listener.start()

asyncio.run(sprite_animation(
    duration=60.0,
    fps=8.0,
    speed=1,
))

listener.stop()
